#include <stdio.h>

int main(void) {
    int s;
    if (scanf("%d", &s) != 1 || s < 0 || s > 100) { printf("invalid\n"); return 1; }
    char g = s >= 90 ? 'A' : s >= 75 ? 'B' : s >= 60 ? 'C' : 'F';
    printf("score=%d grade=%c\n", s, g);
    return 0;
}
